import sys
import heapq
from collections import deque

class PriorityQueue:
    def __init__(self):
        self.heap = []
        self.counter = 0

    def enqueue(self, value, priority):
        # Use negative priority for max-heap (min-heap in Python)
        # Use counter as tie-breaker to maintain FIFO order for same priority
        heapq.heappush(self.heap, (-priority, self.counter, value))
        self.counter += 1

    def dequeue(self):
        if self.is_empty():
            return -1
        _, _, value = heapq.heappop(self.heap)
        return value

    def peek(self):
        if self.is_empty():
            return -1
        _, _, value = self.heap[0]
        return value

    def is_empty(self):
        return len(self.heap) == 0

def main():
    n = int(sys.stdin.readline().strip())
    pq = PriorityQueue()

    for _ in range(n):
        line = sys.stdin.readline().strip()
        parts = line.split()

        if parts[0] == "ENQUEUE":
            value = int(parts[1])
            priority = int(parts[2])
            pq.enqueue(value, priority)
        elif parts[0] == "DEQUEUE":
            result = pq.dequeue()
            print(result)
        elif parts[0] == "PEEK":
            result = pq.peek()
            print(result)

if __name__ == "__main__":
    main()
